-- Plan « Seuil et puissance critique en aéro » (4 semaines) : 14 séances,
-- objectif aéro et indicateur de réussite (passages en TT validés) par séance.
-- Textes en 9 langues assemblés depuis des gabarits par type. Rejouable.

WITH tpl(typ, lang, name, obj, info) AS (VALUES

('t_cp', 'fr', 'Puissance critique TT {n}×{d}', 'Tenir la position TT à 108-115 % FTP sur des efforts de 3 à 4 minutes. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Efforts de 3 à 4 minutes au-dessus du seuil, en TT : l''allure d''un prologue ou d''un CLM court. Récupération égale à l''effort, redressé.'),
('t_cp', 'en', 'TT critical power {n}×{d}', 'Hold the TT position at 108-115% FTP over 3 to 4 minute efforts. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', '3 to 4 minute efforts above threshold, in TT: the pace of a prologue or a short TT. Recovery as long as the effort, upright.'),
('t_cp', 'es', 'Potencia crítica TT {n}×{d}', 'Mantener la posición TT al 108-115 % FTP en esfuerzos de 3 a 4 minutos. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Esfuerzos de 3 a 4 minutos por encima del umbral, en TT: el ritmo de un prólogo o de una CRI corta. Recuperación igual al esfuerzo, erguido.'),
('t_cp', 'it', 'Potenza critica TT {n}×{d}', 'Tenere la posizione TT al 108-115 % FTP su sforzi da 3 a 4 minuti. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Sforzi da 3 a 4 minuti sopra soglia, in TT: il ritmo di un prologo o di una crono corta. Recupero pari allo sforzo, eretto.'),
('t_cp', 'de', 'Kritische Leistung TT {n}×{d}', 'Die TT-Position bei 108-115 % FTP über 3 bis 4 Minuten halten. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', '3- bis 4-minütige Belastungen über der Schwelle, in TT: das Tempo eines Prologs oder kurzen Zeitfahrens. Erholung so lang wie die Belastung, aufrecht.'),
('t_cp', 'nl', 'Kritisch vermogen TT {n}×{d}', 'De TT-houding vasthouden op 108-115 % FTP bij inspanningen van 3 tot 4 minuten. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Inspanningen van 3 tot 4 minuten boven drempel, in TT: het tempo van een proloog of korte tijdrit. Herstel even lang als de inspanning, rechtop.'),
('t_cp', 'pt', 'Potência crítica TT {n}×{d}', 'Manter a posição TT a 108-115 % FTP em esforços de 3 a 4 minutos. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Esforços de 3 a 4 minutos acima do limiar, em TT: o ritmo de um prólogo ou de um contrarrelógio curto. Recuperação igual ao esforço, ereto.'),
('t_cp', 'ja', 'TTクリティカルパワー {n}×{d}', '3〜4分の努力で108〜115 % FTPのTTポジションを保つ。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', '閾値を超える3〜4分の努力をTTで：プロローグや短いTTのペース。回復は努力と同じ長さ、起き上がって。'),
('t_cp', 'tr', 'TT kritik güç {n}×{d}', '3-4 dakikalık eforlarda %108-115 FTP''de TT pozisyonunu koru. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'TT''de eşiğin üzerinde 3-4 dakikalık eforlar: prolog ya da kısa zamana karşı temposu. Eforla eşit toparlanma, dik.'),
('t_ou', 'fr', 'Sur-sous TT {n}×{d}', 'Alterner 1'' à 108 % et 1'' à 95 % FTP sans quitter la position TT. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Les sur-sous font monter la puissance critique : chaque minute au-dessus du seuil est suivie d''une minute juste en dessous, sans vraie récupération, et tout se fait en TT. Pause redressée entre les séries.'),
('t_ou', 'en', 'TT over-unders {n}×{d}', 'Alternate 1'' at 108% and 1'' at 95% FTP without leaving the TT position. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Over-unders raise critical power: each minute above threshold is followed by a minute just below, with no real recovery, all in TT. Upright break between sets.'),
('t_ou', 'es', 'Sobre-bajo TT {n}×{d}', 'Alternar 1'' al 108 % y 1'' al 95 % FTP sin dejar la posición TT. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Los sobre-bajo suben la potencia crítica: cada minuto por encima del umbral va seguido de un minuto justo por debajo, sin recuperación real, todo en TT. Pausa erguido entre series.'),
('t_ou', 'it', 'Sopra-sotto TT {n}×{d}', 'Alternare 1'' al 108 % e 1'' al 95 % FTP senza lasciare la posizione TT. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'I sopra-sotto alzano la potenza critica: ogni minuto sopra soglia è seguito da un minuto appena sotto, senza vero recupero, tutto in TT. Pausa eretto tra le serie.'),
('t_ou', 'de', 'TT-Over-Under {n}×{d}', '1'' bei 108 % und 1'' bei 95 % FTP abwechseln, ohne die TT-Position zu verlassen. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Over-Under steigern die kritische Leistung: Auf jede Minute über der Schwelle folgt eine Minute knapp darunter, ohne echte Erholung, alles in TT. Aufrechte Pause zwischen den Serien.'),
('t_ou', 'nl', 'TT-over-unders {n}×{d}', '1'' op 108 % en 1'' op 95 % FTP afwisselen zonder de TT-houding te verlaten. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Over-unders verhogen het kritisch vermogen: elke minuut boven drempel wordt gevolgd door een minuut net eronder, zonder echt herstel, alles in TT. Pauze rechtop tussen de series.'),
('t_ou', 'pt', 'Acima-abaixo TT {n}×{d}', 'Alternar 1'' a 108 % e 1'' a 95 % FTP sem sair da posição TT. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Os acima-abaixo aumentam a potência crítica: cada minuto acima do limiar é seguido de um minuto logo abaixo, sem recuperação real, tudo em TT. Pausa ereto entre as séries.'),
('t_ou', 'ja', 'TTオーバーアンダー {n}×{d}', 'TTポジションのまま108 %と95 % FTPを1分ずつ交互に。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', 'オーバーアンダーはクリティカルパワーを高めます。閾値を超える1分の後に閾値直下の1分、実質的な回復はなく、全てTTで。セット間は起き上がって休憩。'),
('t_ou', 'tr', 'TT üst-alt {n}×{d}', 'TT pozisyonundan çıkmadan 1'' %108 ve 1'' %95 FTP dönüşümlü. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Üst-alt çalışmaları kritik gücü artırır: eşiğin üstündeki her dakikayı gerçek toparlanma olmadan eşiğin hemen altında bir dakika izler, hepsi TT''de. Setler arasında dik mola.'),
('t_ss', 'fr', 'Sweet spot TT {n}×{d}', 'Tenir la position TT à 88-92 % FTP sur des blocs longs. Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Le sweet spot développe la FTP avec une fatigue mesurée. En TT, c''est l''allure d''un CLM de 40 km à 1 h : la position doit tenir sous l''effort.'),
('t_ss', 'en', 'TT sweet spot {n}×{d}', 'Hold the TT position at 88-92% FTP over long blocks. Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Sweet spot builds FTP with moderate fatigue. In TT, it''s the pace of a 40 km TT or a 1 h effort: the position must hold under effort.'),
('t_ss', 'es', 'Sweet spot TT {n}×{d}', 'Mantener la posición TT al 88-92 % FTP en bloques largos. Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'El sweet spot desarrolla la FTP con una fatiga moderada. En TT es el ritmo de una CRI de 40 km o de 1 h: la posición debe aguantar con el esfuerzo.'),
('t_ss', 'it', 'Sweet spot TT {n}×{d}', 'Tenere la posizione TT all''88-92 % FTP su blocchi lunghi. Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Lo sweet spot sviluppa la FTP con una fatica misurata. In TT è il ritmo di una crono di 40 km o di 1 h: la posizione deve tenere sotto sforzo.'),
('t_ss', 'de', 'TT-Sweet-Spot {n}×{d}', 'Die TT-Position bei 88-92 % FTP über lange Blöcke halten. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Sweet Spot entwickelt die FTP bei moderater Ermüdung. In TT ist es das Tempo eines 40-km-Zeitfahrens oder einer Stunde: Die Position muss unter Belastung halten.'),
('t_ss', 'nl', 'TT-sweetspot {n}×{d}', 'De TT-houding vasthouden op 88-92 % FTP over lange blokken. Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Sweet spot ontwikkelt de FTP met beperkte vermoeidheid. In TT is het het tempo van een tijdrit van 40 km of 1 uur: de houding moet standhouden onder inspanning.'),
('t_ss', 'pt', 'Sweet spot TT {n}×{d}', 'Manter a posição TT a 88-92 % FTP em blocos longos. Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'O sweet spot desenvolve a FTP com fadiga moderada. Em TT, é o ritmo de um contrarrelógio de 40 km ou de 1 h: a posição tem de aguentar sob esforço.'),
('t_ss', 'ja', 'TTスイートスポット {n}×{d}', '長いブロックで88〜92 % FTPのTTポジションを保つ。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', 'スイートスポットは疲労を抑えつつFTPを伸ばします。TTでは40 km TTや1時間の努力のペース：負荷の下でも姿勢を保つこと。'),
('t_ss', 'tr', 'TT sweet spot {n}×{d}', 'Uzun bloklarda %88-92 FTP''de TT pozisyonunu koru. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Sweet spot, ölçülü yorgunlukla FTP''yi geliştirir. TT''de 40 km''lik zamana karşı ya da 1 saatlik efor temposudur: pozisyon efor altında dayanmalı.'),
('t_thr', 'fr', 'Seuil TT {n}×{d}', 'Tenir la position TT au seuil (95-100 % FTP). Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Blocs au seuil entièrement en TT : c''est là que la position coûte le plus, parce que la respiration et la fatigue poussent à se relever. Récupère redressé.'),
('t_thr', 'en', 'TT threshold {n}×{d}', 'Hold the TT position at threshold (95-100% FTP). Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Threshold blocks entirely in TT: this is where the position costs the most, because breathing and fatigue push you to sit up. Recover upright.'),
('t_thr', 'es', 'Umbral TT {n}×{d}', 'Mantener la posición TT en el umbral (95-100 % FTP). Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Bloques de umbral totalmente en TT: aquí es donde más cuesta la posición, porque la respiración y la fatiga empujan a incorporarse. Recupera erguido.'),
('t_thr', 'it', 'Soglia TT {n}×{d}', 'Tenere la posizione TT alla soglia (95-100 % FTP). Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Blocchi alla soglia interamente in TT: è qui che la posizione costa di più, perché respiro e fatica spingono a rialzarsi. Recupera eretto.'),
('t_thr', 'de', 'TT-Schwelle {n}×{d}', 'Die TT-Position an der Schwelle (95-100 % FTP) halten. Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Schwellenblöcke komplett in TT: Hier kostet die Position am meisten, weil Atmung und Ermüdung zum Aufrichten drängen. Aufrecht erholen.'),
('t_thr', 'nl', 'TT-drempel {n}×{d}', 'De TT-houding vasthouden op drempel (95-100 % FTP). Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Drempelblokken volledig in TT: hier kost de houding het meest, omdat ademhaling en vermoeidheid je overeind duwen. Herstel rechtop.'),
('t_thr', 'pt', 'Limiar TT {n}×{d}', 'Manter a posição TT no limiar (95-100 % FTP). Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Blocos no limiar inteiramente em TT: é aqui que a posição mais custa, porque a respiração e a fadiga empurram para levantar. Recupere ereto.'),
('t_thr', 'ja', 'TT閾値 {n}×{d}', '閾値（95〜100 % FTP）でTTポジションを保つ。 達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', '閾値ブロックを全てTTで：呼吸と疲労で起き上がりたくなるため、最も姿勢を保つのが難しい強度です。回復は起き上がって。'),
('t_thr', 'tr', 'TT eşik {n}×{d}', 'Eşikte (%95-100 FTP) TT pozisyonunu koru. Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Tamamen TT''de eşik blokları: nefes ve yorgunluk doğrulmaya ittiği için pozisyonun en çok zorladığı yer burası. Dik toparlan.')
), wk(lang, p) AS (VALUES ('fr', 'S'), ('en', 'W'), ('es', 'S'), ('it', 'S'), ('de', 'W'), ('nl', 'W'), ('pt', 'S'), ('ja', 'W'), ('tr', 'H')
), s(skey, typ, week, n, d, minutes, k, aero, blocks, lc) AS (VALUES

