('threshold_tt_4w_w2s2', 't_ou', 2, '3', '6×1''', 59, 36, 2160, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 108.0, "power_end": 95.0, "duration_work": 60, "duration_recup": 60, "repetitions": 6, "position": "prolongateurs", "position_recup": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 55.0, "duration_work": 240}, {"type": "FRAC", "unit": "% FTP", "power_start": 108.0, "power_end": 95.0, "duration_work": 60, "duration_recup": 60, "repetitions": 6, "position": "prolongateurs", "position_recup": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 55.0, "duration_work": 240}, {"type": "FRAC", "unit": "% FTP", "power_start": 108.0, "power_end": 95.0, "duration_work": 60, "duration_recup": 60, "repetitions": 6, "position": "prolongateurs", "position_recup": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 660, "key": "threshold_tt_4w_lc_recup", "duration": 12}, {"at": 1550, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 2510, "key": "threshold_tt_4w_lc_start", "duration": 12}]'::jsonb),
