('threshold_tt_4w_w3s4', 't_cp', 3, '5', '4''', 55, 5, 1200, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 110.0, "power_end": 55.0, "duration_work": 240, "duration_recup": 240, "repetitions": 5, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 1070, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 1550, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 2030, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 2510, "key": "threshold_tt_4w_lc_start", "duration": 12}]'::jsonb),
('threshold_tt_4w_w4s1', 't_ss', 4, '2', '12''', 49, 2, 1440, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 90.0, "power_end": 55.0, "duration_work": 720, "duration_recup": 300, "repetitions": 2, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 1610, "key": "threshold_tt_4w_lc_start", "duration": 12}]'::jsonb),
('threshold_tt_4w_w4s2', 't_thr', 4, '3', '6''', 42, 3, 1080, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 98.0, "power_end": 55.0, "duration_work": 360, "duration_recup": 180, "repetitions": 3, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 1130, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 1670, "key": "threshold_tt_4w_lc_start", "duration": 12}]'::jsonb),
('threshold_tt_4w_w4s3', 't_cp', 4, '4', '3''', 44, 5, 1020, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 600}, {"type": "FRAC", "unit": "% FTP", "power_start": 110.0, "power_end": 55.0, "duration_work": 180, "duration_recup": 180, "repetitions": 4, "position": "prolongateurs"}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 300, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 590, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 950, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 1310, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 1670, "key": "threshold_tt_4w_lc_start", "duration": 12}, {"at": 2030, "key": "threshold_tt_4w_lc_start", "duration": 12}]'::jsonb)
), built AS (
  SELECT s.*,
    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, replace(t.obj, '{k}', s.k::text)) FROM tpl t WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
INSERT INTO public.training_sessions (name, info, objectif, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT b.skey || '_name', b.skey || '_info', b.skey || '_objectif',
  jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  b.minutes, false, b.lc,
  jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"threshold_tt_4w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "threshold_tt_4w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "threshold_tt_4w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "threshold_tt_4w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  b.aero
FROM built b
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions ts WHERE ts.name = b.skey || '_name');

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'threshold_tt_4w_name', 'threshold_tt_4w_description', 'threshold_tt_4w_objective', 4, 'advanced', 'training', 4, true, '{"name": {"fr": "Seuil et puissance critique en aéro", "en": "Threshold and critical power in aero", "es": "Umbral y potencia crítica en aero", "it": "Soglia e potenza critica in aero", "de": "Schwelle und kritische Leistung in Aero", "nl": "Drempel en kritisch vermogen in aero", "pt": "Limiar e potência crítica em aero", "ja": "エアロでの閾値とクリティカルパワー", "tr": "Aero''da eşik ve kritik güç"}, "objective": {"fr": "Faire monter ta FTP et ta puissance critique en les produisant en position TT (90-115 % FTP).", "en": "Raise your FTP and critical power by producing them in the TT position (90-115% FTP).", "es": "Subir tu FTP y tu potencia crítica produciéndolas en posición TT (90-115 % FTP).", "it": "Alzare FTP e potenza critica producendole in posizione TT (90-115 % FTP).", "de": "FTP und kritische Leistung steigern, indem du sie in TT-Position erbringst (90-115 % FTP).", "nl": "Je FTP en kritisch vermogen verhogen door ze in TT-houding te leveren (90-115 % FTP).", "pt": "Aumentar sua FTP e potência crítica produzindo-as na posição TT (90-115 % FTP).", "ja": "TTポジションで出すことでFTPとクリティカルパワーを高める（90〜115 % FTP）。", "tr": "FTP''ni ve kritik gücünü TT pozisyonunda üreterek yükselt (%90-115 FTP)."}, "description": {"fr": "4 semaines, 3 à 4 séances de 40 à 75 minutes, tous les efforts en TT : sweet spot (88-92 % FTP) de 10 à 20 minutes, seuil (95-100 % FTP) de 6 à 12 minutes, sur-sous (108/95 % FTP) et puissance critique (110-115 % FTP) sur 3 à 4 minutes. La puissance que tu développes est celle que tu sauras tenir en course, dans ta position.", "en": "4 weeks, 3 to 4 sessions of 40 to 75 minutes, all efforts in TT: sweet spot (88-92% FTP) for 10 to 20 minutes, threshold (95-100% FTP) for 6 to 12 minutes, over-unders (108/95% FTP) and critical power (110-115% FTP) over 3 to 4 minutes. The power you build is the power you''ll hold in a race, in your position.", "es": "4 semanas, 3 a 4 sesiones de 40 a 75 minutos, todos los esfuerzos en TT: sweet spot (88-92 % FTP) de 10 a 20 minutos, umbral (95-100 % FTP) de 6 a 12 minutos, sobre-bajo (108/95 % FTP) y potencia crítica (110-115 % FTP) de 3 a 4 minutos. La potencia que desarrollas es la que sabrás mantener en carrera, en tu posición.", "it": "4 settimane, da 3 a 4 sessioni da 40 a 75 minuti, tutti gli sforzi in TT: sweet spot (88-92 % FTP) da 10 a 20 minuti, soglia (95-100 % FTP) da 6 a 12 minuti, sopra-sotto (108/95 % FTP) e potenza critica (110-115 % FTP) su 3-4 minuti. La potenza che sviluppi è quella che saprai tenere in gara, nella tua posizione.", "de": "4 Wochen, 3 bis 4 Einheiten von 40 bis 75 Minuten, alle Belastungen in TT: Sweet Spot (88-92 % FTP) über 10 bis 20 Minuten, Schwelle (95-100 % FTP) über 6 bis 12 Minuten, Over-Under (108/95 % FTP) und kritische Leistung (110-115 % FTP) über 3 bis 4 Minuten. Die Leistung, die du aufbaust, kannst du im Rennen in deiner Position halten.", "nl": "4 weken, 3 tot 4 sessies van 40 tot 75 minuten, alle inspanningen in TT: sweet spot (88-92 % FTP) van 10 tot 20 minuten, drempel (95-100 % FTP) van 6 tot 12 minuten, over-unders (108/95 % FTP) en kritisch vermogen (110-115 % FTP) over 3 tot 4 minuten. Het vermogen dat je opbouwt, kun je in wedstrijd vasthouden, in je houding.", "pt": "4 semanas, 3 a 4 sessões de 40 a 75 minutos, todos os esforços em TT: sweet spot (88-92 % FTP) de 10 a 20 minutos, limiar (95-100 % FTP) de 6 a 12 minutos, acima-abaixo (108/95 % FTP) e potência crítica (110-115 % FTP) em 3 a 4 minutos. A potência que você desenvolve é a que saberá manter em prova, na sua posição.", "ja": "4週間、40〜75分のセッションを週3〜4回、全ての努力をTTで：スイートスポット（88〜92 % FTP）10〜20分、閾値（95〜100 % FTP）6〜12分、オーバーアンダー（108/95 % FTP）、クリティカルパワー（110〜115 % FTP）3〜4分。伸ばしたパワーは、レースで自分のポジションのまま維持できるパワーです。", "tr": "4 hafta, haftada 40-75 dakikalık 3-4 seans, tüm eforlar TT''de: 10-20 dakika sweet spot (%88-92 FTP), 6-12 dakika eşik (%95-100 FTP), üst-alt (%108/95 FTP) ve 3-4 dakikada kritik güç (%110-115 FTP). Geliştirdiğin güç, yarışta kendi pozisyonunda koruyabileceğin güçtür."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'threshold_tt_4w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'threshold_tt_4w_w1s1_name'), (1, 2, 'threshold_tt_4w_w1s2_name'), (1, 3, 'threshold_tt_4w_w1s3_name'), (2, 1, 'threshold_tt_4w_w2s1_name'), (2, 2, 'threshold_tt_4w_w2s2_name'), (2, 3, 'threshold_tt_4w_w2s3_name'), (2, 4, 'threshold_tt_4w_w2s4_name'), (3, 1, 'threshold_tt_4w_w3s1_name'), (3, 2, 'threshold_tt_4w_w3s2_name'), (3, 3, 'threshold_tt_4w_w3s3_name'), (3, 4, 'threshold_tt_4w_w3s4_name'), (4, 1, 'threshold_tt_4w_w4s1_name'), (4, 2, 'threshold_tt_4w_w4s2_name'), (4, 3, 'threshold_tt_4w_w4s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'threshold_tt_4w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);
